CREATE TABLE categories (id INT PRIMARY KEY, name VARCHAR(255) NOT NULL) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
CREATE TABLE dictionary (
 id INT PRIMARY KEY, category_id INT NOT NULL, status VARCHAR(24) NOT NULL,
 tolour_word TEXT NOT NULL, indonesian_meaning TEXT NOT NULL,
 popularity DOUBLE NOT NULL, search_count BIGINT NOT NULL
) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
